INSERT INTO public.companies (slug, name, subsector_id, website, chains, tags, meta)
SELECT v.slug, v.name, s.id, v.website, v.chains, v.tags, v.meta
FROM (VALUES
  ('gcash', 'GCash', 'monetary-access-rails', 'regional-payment-networks', 'https://www.gcash.com', ARRAY['Ethereum Mainnet (partner-dependent', 'pilot', 'indirect usage)']::text[], ARRAY[]::text[], '{"description": "GCash is the Philippines’ dominant mobile payments platform, enabling domestic payments and financial services at massive scale. While users do not access crypto directly, Ethereum-based stablecoins may be used indirectly in backend settlement through remittance and payment partners.", "extras": {"Availability Expectations": "Consumer-grade, high-availability", "Custody Model": "Centralized platform custody (e-money model)", "Ethereum Dependency Level": "Minimal–Replaceable (Ethereum optional and invisible)", "Ethereum Role in Stack": "Anchored / indirect settlement layer (stablecoin rails via partners, pilots)", "FX Model": "Offchain FX for consumer flows; onchain stablecoin settlement in backend corridors", "Failure Mode": "Reversion to fiat-only settlement; crypto rails disabled", "Geographic Scope": "Single country (Philippines)", "Interaction with DeFi": "None", "Interaction with Global On-Ramps": "Indirect (remittance and payment partners)", "Interaction with Institutional Payment Rails": "Indirect (bank and remittance settlement partners)", "Is Ethereum Abstracted from End Users?": "Yes (users never interact with blockchain directly)", "KYC / AML Enforcement Level": "Full (BSP-compliant, tiered limits)", "Key Payment Corridors": "Domestic Philippines; Philippines ↔ global remittance corridors (via partners)", "Local Currency Support": "Yes (PHP-native)", "Local Problem Addressed": "Cash dependence, fragmented domestic payments, limited access to formal banking", "Maintaining Organization": "G-Xchange, Inc. (GCash)", "Practitioner Validation Check": "Is geographic focus a hard design constraint, and does Ethereum materially enable settlement somewhere in the payment stack? Yes (indirect / partner-mediated)", "Practitioner’s Note": "GCash is distribution without protocol visibility: Ethereum matters only if embedded in partner settlement layers; adoption is policy- and partner-driven rather than product-driven.", "Primary Dependency Risks": "Regulatory constraints, partner banks/remittance providers", "Primary Function": "Domestic mobile payments, e-wallet services, and bill payments", "Primary Jurisdiction(s)": "Philippines", "Primary Region / Geography Served": "Philippines", "Primary Settlement Currency": "PHP (domestic); USD stablecoins for cross-border partner settlement", "Reason for Inclusion": "GCash qualifies as a Regional Payment Network because it is structurally constrained to the Philippines and, through partners, touches Ethereum-based settlement rails for cross-border and remittance flows—even though blockchain is fully abstracted from users.", "Regional Adoption Level": "Very High", "Regional Constraint Type": "Domestic payment fragmentation / Banking access", "Regulatory Posture": "Fully regulated e-money issuer (BSP-licensed)", "Settlement Asset Types": "Stablecoins (USDC/USDT via partners; not user-facing)", "Settlement vs Access Orientation": "Access-First (Settlement-Abstracted)", "Systemic Importance to Ethereum (Regional)": "Low–Medium", "Target User Segment": "Consumers, merchants, MSMEs", "Transaction Scale": "Low-value / very high-frequency"}, "source_label": "Regional Payment Networks"}'::jsonb),
  ('monerium', 'Monerium', 'monetary-access-rails', 'regional-payment-networks', 'https://monerium.com', ARRAY['Ethereum Mainnet', 'Ethereum L2s (e.g.', 'Optimism', 'Arbitrum)']::text[], ARRAY[]::text[], '{"description": "Monerium issues fully regulated e-money directly on Ethereum, enabling onchain euro, pound, and krona balances that can move natively on public blockchains while remaining redeemable 1:1 into the European banking system.", "extras": {"Availability Expectations": "Payments- and banking-grade", "Custody Model": "Non-custodial onchain balances; regulated redemption accounts", "Ethereum Dependency Level": "Critical (Ethereum is the monetary rail, not optional)", "Ethereum Role in Stack": "Native settlement layer (e-money issued directly on Ethereum)", "FX Model": "Onchain settlement with offchain banking rails for redemption; FX external", "Failure Mode": "Issuance paused; redemption restricted; fallback to SEPA rails", "Founded Year": "2016", "Geographic Scope": "Multi-country region (Europe / EEA)", "Interaction with DeFi": "Limited / gated (regulatory constraints)", "Interaction with Global On-Ramps": "Direct (bank account integration)", "Interaction with Institutional Payment Rails": "Direct (banking system ↔ Ethereum settlement)", "Is Ethereum Abstracted from End Users?": "No (onchain balances are first-class monetary objects)", "KYC / AML Enforcement Level": "Full (EEA-grade compliance)", "Key Payment Corridors": "Intra-EEA; onchain ↔ SEPA bank accounts", "Local Currency Support": "Yes (EUR, GBP, ISK)", "Local Problem Addressed": "Fragmented European payments, limited programmability of bank money, lack of compliant onchain euros", "Maintaining Organization": "Monerium ehf.", "Practitioner Validation Check": "Is the payment network regionally constrained by regulation, and does Ethereum serve as the authoritative settlement layer for fiat-denominated value? Yes", "Practitioner’s Note": "Monerium is Europe’s cleanest fiat–Ethereum bridge: unlike stablecoins, money is issued as e-money onchain, making Ethereum part of the regulated monetary perimeter.", "Primary Dependency Risks": "Banking partners, regulatory changes to EMI frameworks", "Primary Function": "Onchain fiat payments and settlement via regulated e-money", "Primary Jurisdiction(s)": "Iceland (EEA passported)", "Primary Region / Geography Served": "Europe (EEA)", "Primary Settlement Currency": "EUR (EURe)", "Reason for Inclusion": "Monerium qualifies as a Regional Payment Network because it is structurally constrained to Europe by regulation and uses Ethereum as the primary settlement layer for compliant fiat payments, not merely as a backend optimization.", "Regional Adoption Level": "Medium", "Regional Constraint Type": "Regulatory perimeter / Banking integration", "Regulatory Posture": "Fully regulated E-Money Institution (EMI)", "Settlement Asset Types": "Regulated e-money tokens (EURe, GBPe, ISKe)", "Settlement vs Access Orientation": "Settlement-First", "Systemic Importance to Ethereum (Regional)": "High", "Target User Segment": "Fintechs, enterprises, DAOs, Web3-native organizations", "Transaction Scale": "Low- to high-value (enterprise and treasury flows)"}, "source_label": "Regional Payment Networks"}'::jsonb),
  ('quantoz', 'Quantoz', 'monetary-access-rails', 'regional-payment-networks', 'https://www.quantoz.com', ARRAY['Ethereum Mainnet', 'Ethereum L2s (deployment-dependent)']::text[], ARRAY[]::text[], '{"description": "Quantoz provides regulated euro-denominated digital money infrastructure, issuing compliant euro tokens on public blockchains like Ethereum to enable programmable, onchain settlement fully integrated with the European banking system.", "extras": {"Availability Expectations": "Payments- and banking-grade", "Custody Model": "Onchain balances with regulated redemption accounts; non-custodial at protocol level", "Ethereum Dependency Level": "Critical (Ethereum is the monetary rail, not optional)", "Ethereum Role in Stack": "Native settlement layer (regulated euro tokens issued on Ethereum)", "FX Model": "Onchain euro settlement; FX handled externally via banking partners", "Failure Mode": "Issuance paused; redemption constrained; fallback to SEPA", "Founded Year": "2015", "Geographic Scope": "Multi-country region (Europe / EEA)", "Interaction with DeFi": "Limited / permissioned (regulatory gating)", "Interaction with Global On-Ramps": "Direct (bank account funding and redemption)", "Interaction with Institutional Payment Rails": "Direct (banking system ↔ Ethereum settlement)", "Is Ethereum Abstracted from End Users?": "No (onchain balances are first-class monetary objects)", "KYC / AML Enforcement Level": "Full (EEA-grade compliance)", "Key Payment Corridors": "Intra-EEA; onchain ↔ SEPA bank accounts", "Local Currency Support": "EUR", "Local Problem Addressed": "Lack of compliant, programmable euro-denominated digital settlement instruments", "Maintaining Organization": "Quantoz Payments B.V.", "Practitioner Validation Check": "Is the network regionally constrained by EU regulation, and does Ethereum directly host the fiat-denominated settlement asset? Yes", "Practitioner’s Note": "Quantoz represents EU-native programmable money: closer to onchain bank money than private stablecoins, with Ethereum functioning as regulated settlement infrastructure.", "Primary Dependency Risks": "Banking partners, regulatory interpretation of e-money onchain", "Primary Function": "Regulated euro-denominated digital money and settlement", "Primary Jurisdiction(s)": "Netherlands (EEA passporting)", "Primary Region / Geography Served": "Europe (Eurozone / EEA)", "Primary Settlement Currency": "EUR", "Reason for Inclusion": "Quantoz qualifies as a Regional Payment Network because it is structurally constrained to Europe by regulation and uses Ethereum as the authoritative settlement layer for euro-denominated digital money rather than as a secondary optimization layer.", "Regional Adoption Level": "Early", "Regional Constraint Type": "Regulatory perimeter / Eurozone banking integration", "Regulatory Posture": "Regulated E-Money Institution (EMI) / compliant under EU frameworks", "Settlement Asset Types": "Regulated euro-denominated tokens (e.g., EURD, EURQ variants depending on issuance program)", "Settlement vs Access Orientation": "Settlement-First", "Systemic Importance to Ethereum (Regional)": "High", "Target User Segment": "Fintechs, enterprises, Web3 platforms, institutional users", "Transaction Scale": "Medium- to high-value (enterprise and treasury settlement)"}, "source_label": "Regional Payment Networks"}'::jsonb),
  ('stasis', 'Stasis', 'monetary-access-rails', 'regional-payment-networks', 'https://stasis.net', ARRAY['Ethereum Mainnet', 'selective Ethereum L2 support']::text[], ARRAY[]::text[], '{"description": "Stasis issues EURS, a euro-denominated stablecoin backed by offchain fiat reserves, enabling euro settlement on Ethereum while integrating with European banking infrastructure for issuance and redemption.", "extras": {"Availability Expectations": "Payments- and settlement-grade", "Custody Model": "Onchain token custody; offchain fiat reserves held with regulated partners", "Ethereum Dependency Level": "Critical (Ethereum hosts the euro-denominated asset)", "Ethereum Role in Stack": "Native settlement layer (EUR-backed tokens issued on Ethereum)", "FX Model": "Onchain euro settlement; FX handled externally", "Failure Mode": "Issuance or redemption halted; fallback to banking rails", "Founded Year": "2018", "Geographic Scope": "Multi-country region (Europe)", "Interaction with DeFi": "Limited (select integrations; compliance-constrained)", "Interaction with Global On-Ramps": "Indirect (exchanges, fintech partners)", "Interaction with Institutional Payment Rails": "Indirect (banking and custody partners)", "Is Ethereum Abstracted from End Users?": "No (onchain balances are the monetary object)", "KYC / AML Enforcement Level": "Full (issuer- and partner-enforced)", "Key Payment Corridors": "Intra-Europe; onchain ↔ EU banking rails", "Local Currency Support": "EUR", "Local Problem Addressed": "Lack of euro-native digital settlement assets usable across blockchain and fintech rails", "Maintaining Organization": "STASIS Ltd.", "Practitioner Validation Check": "Is the network regionally constrained to Europe and does Ethereum directly host the euro-denominated settlement asset? Yes", "Practitioner’s Note": "Stasis sits between private stablecoins and regulated e-money: Ethereum is the settlement rail, but regulatory durability depends on MiCA alignment and reserve governance.", "Primary Dependency Risks": "Regulatory interpretation (MiCA), banking partners, reserve transparency", "Primary Function": "Euro-denominated digital settlement via fiat-backed stablecoins", "Primary Jurisdiction(s)": "Malta / EU-facing operations", "Primary Region / Geography Served": "Europe (EEA-focused)", "Primary Settlement Currency": "EUR", "Reason for Inclusion": "Stasis qualifies as a Regional Payment Network because it is structurally focused on Europe and uses Ethereum as the settlement layer for euro-denominated value, bridging EU banking rails with onchain payments.", "Regional Adoption Level": "Medium", "Regional Constraint Type": "Eurozone regulation / Banking integration", "Regulatory Posture": "EU-compliant structure; operates within evolving EU stablecoin frameworks", "Settlement Asset Types": "Fiat-backed stablecoins (EURS)", "Settlement vs Access Orientation": "Settlement-First", "Systemic Importance to Ethereum (Regional)": "Medium–High", "Target User Segment": "Crypto-native users, fintechs, enterprises, exchanges", "Transaction Scale": "Medium (trading, settlement, treasury use cases)"}, "source_label": "Regional Payment Networks"}'::jsonb),
  ('moneygram', 'MoneyGram', 'monetary-access-rails', 'regional-payment-networks', 'https://www.moneygram.com', ARRAY['Ethereum Mainnet (USDC settlement via partners)']::text[], ARRAY[]::text[], '{"description": "MoneyGram is one of the world’s largest remittance networks. Through integrations with stablecoin issuers such as Circle, it has used Ethereum-based USDC settlement to optimize cross-border liquidity and reduce pre-funding requirements, while keeping blockchain fully abstracted from consumers.", "extras": {"Availability Expectations": "Consumer-grade, cash-reliant uptime", "Custody Model": "Institutional custody via partners (e.g., Circle, custodians)", "Ethereum Dependency Level": "Important (improves liquidity efficiency but replaceable)", "Ethereum Role in Stack": "Anchored / optional settlement layer (stablecoin settlement for cross-border liquidity)", "FX Model": "Hybrid (offchain FX + onchain stablecoin settlement between hubs)", "Failure Mode": "Reversion to correspondent banking and pre-funded nostro/vostro accounts", "Founded Year": "1940", "Geographic Scope": "Multi-region (U.S.-origin with regional payout specialization)", "Interaction with DeFi": "None", "Interaction with Global On-Ramps": "Indirect (bank funding, cash locations)", "Interaction with Institutional Payment Rails": "Direct (stablecoin issuers, custody and settlement partners)", "Is Ethereum Abstracted from End Users?": "Yes (retail users interact with cash and fiat rails only)", "KYC / AML Enforcement Level": "Full (global MSB and corridor-specific compliance)", "Key Payment Corridors": "U.S. ↔ Latin America; U.S. ↔ Africa; U.S. ↔ Asia", "Local Currency Support": "Yes (multi-currency via global payout network)", "Local Problem Addressed": "High cost and latency of international remittances, cash-to-digital interoperability", "Maintaining Organization": "MoneyGram International, Inc.", "Practitioner Validation Check": "Is geographic focus a hard constraint of the remittance network, and does Ethereum materially improve settlement efficiency even if users never see it? Yes", "Practitioner’s Note": "MoneyGram is legacy distribution + modern settlement: Ethereum’s value is operational—liquidity efficiency and faster hub-to-hub settlement—rather than product-level differentiation.", "Primary Dependency Risks": "Regulatory treatment of stablecoins, banking and cash-agent network", "Primary Function": "Retail remittances and cross-border money transfer", "Primary Jurisdiction(s)": "United States", "Primary Region / Geography Served": "United States (origin market) with global regional corridors", "Primary Settlement Currency": "USD", "Reason for Inclusion": "MoneyGram qualifies as a Regional Payment Network because it is structurally anchored in U.S.-origin remittance corridors and uses Ethereum-based stablecoin settlement as backend infrastructure for regional cross-border flows.", "Regional Adoption Level": "Very High", "Regional Constraint Type": "Remittance corridors / Liquidity pre-funding", "Regulatory Posture": "Highly regulated money services business (MSB)", "Settlement Asset Types": "Stablecoins (USDC)", "Settlement vs Access Orientation": "Settlement-Enabled (Access-First UX)", "Systemic Importance to Ethereum (Regional)": "Medium", "Target User Segment": "Consumers, migrant workers, remittance recipients", "Transaction Scale": "Low-value / extremely high-frequency"}, "source_label": "Regional Payment Networks"}'::jsonb),
  ('strike', 'Strike', 'monetary-access-rails', 'regional-payment-networks', 'https://strike.me', ARRAY['Ethereum Mainnet (treasury and settlement legs', 'non-user-facing)']::text[], ARRAY[]::text[], '{"description": "Strike is a U.S.-focused payments application enabling instant consumer and merchant payments. While users transact in dollars, the platform can leverage blockchain-based liquidity and stablecoin rails in backend settlement to reduce cost and latency.", "extras": {"Availability Expectations": "Consumer-grade, near-instant", "Custody Model": "Platform-managed custody (no user onchain custody)", "Ethereum Dependency Level": "Replaceable (Ethereum optional and non-core)", "Ethereum Role in Stack": "Indirect / optional settlement layer (stablecoin treasury and USD liquidity routing)", "FX Model": "Hybrid (offchain USD rails + onchain stablecoin routing for international legs)", "Failure Mode": "Reversion to fiat-only settlement rails", "Founded Year": "2020", "Geographic Scope": "Single country (United States)", "Interaction with DeFi": "None", "Interaction with Global On-Ramps": "Indirect (bank account funding)", "Interaction with Institutional Payment Rails": "Indirect (stablecoin issuers, banking partners)", "Is Ethereum Abstracted from End Users?": "Yes (users never interact with blockchain directly)", "KYC / AML Enforcement Level": "Full (U.S. MSB standards)", "Key Payment Corridors": "U.S. domestic; U.S. ↔ Latin America (select corridors)", "Local Currency Support": "USD (domestic); foreign currencies via corridors", "Local Problem Addressed": "Slow bank settlement, high card fees, expensive cross-border payments", "Maintaining Organization": "Zap Solutions, Inc. (Strike)", "Practitioner Validation Check": "Is geographic focus a hard design constraint and does Ethereum materially contribute somewhere in the settlement stack, even if abstracted? Yes (indirect usage)", "Practitioner’s Note": "Strike is UX-first payments infrastructure: Ethereum, when used, operates as invisible settlement plumbing rather than a user-facing monetary rail.", "Primary Dependency Risks": "Banking partners, regulatory treatment of crypto settlement, stablecoin access", "Primary Function": "Consumer and merchant payments with instant settlement", "Primary Jurisdiction(s)": "United States", "Primary Region / Geography Served": "United States (with selective international corridors)", "Primary Settlement Currency": "USD", "Reason for Inclusion": "Strike qualifies as a Regional Payment Network because it is structurally constrained to the U.S. payments market and uses blockchain-based settlement infrastructure—including Ethereum-linked stablecoins—indirectly to improve payment efficiency.", "Regional Adoption Level": "Medium", "Regional Constraint Type": "Card network fees / Bank settlement latency", "Regulatory Posture": "U.S.-regulated money services business (MSB)", "Settlement Asset Types": "USD stablecoins (USDC/USDT in treasury and cross-border routing contexts)", "Settlement vs Access Orientation": "Access-First (Settlement-Abstracted)", "Systemic Importance to Ethereum (Regional)": "Low–Medium", "Target User Segment": "Consumers, merchants, SMBs", "Transaction Scale": "Low-value / very high-frequency (consumer payments)"}, "source_label": "Regional Payment Networks"}'::jsonb),
  ('euler', 'Euler', 'defi-systems-architecture', 'lending-markets', 'https://www.euler.finance', ARRAY['Over-collateralized borrowing with per-asset risk parameters']::text[], ARRAY[]::text[], '{"description": "A modular lending protocol designed to support permissionless asset onboarding with granular risk controls and onchain liquidation logic.", "extras": {"Collateral Types Supported ERC-20s; ETH; widely supports LST collateral in certain markets (risk-parameter dependent) ERC-20s; ETH (wrapped); selected stablecoins; LST support market-dependent (primarily via governance-approved assets) ETH; ERC-20s; selected LSTs; RWAs (via specialized vaults) ERC-20s + ETH (incl. stETH, DAI, sDAI at launch; asset set is governance/risk-managed) (TradingView) ERC-20s; market-defined collateral/loan pairs (including LSTs, stablecoins, and other ERC-20 collateral depending on market config) (docs.morpho.org)": "ERC-20s; broad long-tail asset support; LSTs/stablecoins market-dependent", "Dependency Concentration Risk High oracle reliance + large-collateral concentration risk (market-dependent); governance/parameter-change latency risk High oracle reliance; Medium–High asset concentration risk in v3 base asset; governance latency risk High oracle reliance; High governance concentration risk; Medium–High RWA dependency risk High oracle reliance + governance/parameter-change latency risk; asset concentration risk (DAI-centric design) (Spark Docs) High oracle dependence (per-market); configuration/parameter risk; integration/curation risk (markets can be permissionlessly created but quality varies) (mixbytes.io)": "High oracle dependence; design-complexity risk; governance execution risk", "Downstream Consumers Yield strategies, leveraged LPs, hedged carry, structured products, derivatives margin users Yield strategies, leveraged positions, DAO treasuries, arbitrage and carry strategies DEX liquidity, lending protocols, yield strategies, derivatives, DAOs, payment rails Yield strategies, stablecoin allocators, leverage users, structured products integrating DAI liquidity Vaults/allocators, structured lending products, leveraged strategies, institutional deployers using Morpho rails": "Yield strategies, leverage protocols, niche asset markets", "Governance Model Token governance (AAVE) via Aave DAO processes; proposals/voting for parameter changes (aave.com) Token governance (COMP) via Compound DAO proposals and voting Token governance (MKR) with executive votes and onchain spell execution Governance via SPK token; Snapshot/signaling and governance system documented by Spark (Spark Docs) Token governance via MORPHO; weighted voting and defined governance powers (docs.morpho.org)": "Token governance (EUL) via Euler DAO", "Historical Stress Events Yes (v1 largely frozen/disabled for new supply/borrow; legacy positions remain manageable) (messari.io) Yes (v2 experienced stress events and governance interventions; migration to v3 reflects risk simplification lessons) Yes (notably March 2020 “Black Thursday” auction failures; subsequent mechanism redesigns) No major protocol-loss event cited in core docs; treat as “monitor” (bug bounty active) (Immunefi) Yes (documented oracle-manipulation event on a specific market; plus a frontend-related incident where contracts unaffected) (Morpho Governance Forum)": "Yes (March 2023 exploit in v1; ~$197M drained, later largely recovered)", "Interest Rate Model Utilization-based variable rates; also supports “stable” borrow rate mode (market-specific) Utilization-based interest rate curves per asset (v2); simplified rate model with base/borrow asset separation (v3) Governance-set stability fees per vault type (effectively interest rates) Utilization-based IR model (Aave v3 lineage) + custom DAI/sDAI strategies in Spark context (Medium) Market-selected Interest Rate Models (IRMs); IRMs/LLTVs are constrained by governance whitelists (docs.morpho.org)": "Utilization-based interest rate models configurable per asset", "Isolation of Risk Risk primarily at market/reserve parameter level (not isolated per-user); isolation features exist in newer versions/markets but not “isolated pools” by default Moderate isolation: v3 introduces asset isolation via a single base asset with segmented collateral; v2 uses shared pools High isolation at vault-type level; each collateral type has independent parameters Shared pool risk by asset/reserve parameters (not per-market isolation like Morpho Blue) High isolation: each market is isolated and immutable by design (docs.morpho.org)": "Moderate–High isolation at asset/module level (not global pools)", "Launch Year 2020 (v1 Ethereum mainnet) (aave.com) 2018 (v2 on Ethereum) 2017 (Single-Collateral DAI; Multi-Collateral DAI in 2019) 2023 (public launch May 9, 2023) (X (formerly Twitter)) 2023 (Morpho Blue introduced Oct 2023) (morpho.org)": "2021", "Lending Model Pooled liquidity markets (multi-asset) Pooled liquidity markets (v2); single-collateral base with isolated borrow assets (v3/Comet) CDP / Vault-based collateralized lending Pooled liquidity markets (Aave v3-derived money market) (Spark Docs) Permissionless, isolated lending markets (1 collateral + 1 loan asset per market) (docs.morpho.org)": "Permissionless, modular lending markets with asset-level isolation", "Liquidation Mechanism Onchain liquidations triggered when Health Factor < 1; liquidators repay debt for collateral + bonus (bonus/thresholds per asset, governance/risk-managed) (aave.com) Onchain liquidations when collateral value breaches borrow limits; liquidators repay debt for collateral at protocol-defined incentives Onchain liquidation via auctions (debt, collateral, surplus); keeper participation required Health Factor-based liquidations (HF < 1), onchain seizure/repay mechanics (Spark Docs) Standard liquidation when LTV exceeds LLTV; liquidators repay debt and seize collateral at discount (protocol-enforced) (docs.morpho.org)": "Onchain liquidations and “soft liquidation” mechanisms (discounted collateral seizure)", "Maintaining Organization Aave DAO (governance) + Aave Labs (major dev & interface/operator tooling) (aave.com) Compound DAO (governance) with historical development by Compound Labs MakerDAO (DAO-governed protocol) with core units / contributors maintaining modules Spark Governance (SPK) operating via the Spark Agent in the Sky Atlas (Sky ecosystem) (Spark Docs) Morpho Governance (MORPHO token); governance whitelists IRMs/LLTVs and can activate fee switch (docs.morpho.org)": "Euler DAO (EUL token) with development historically led by Euler Labs", "Oracle Dependencies Primarily Chainlink price feeds with protocol risk controls (market-config dependent) Chainlink price feeds (primary), with protocol-defined fallbacks/guards Decentralized Oracle Network (Maker Oracles) with Chainlink integrations and redundancy Oracle-driven risk system; Spark has integrated oracle providers (e.g., RedStone) for lending markets (RedStone blog) Oracle per market; Morpho established an oracle wrapper for Chainlink feeds to support initial markets (morpho.org)": "Chainlink oracles + internal risk controls", "Parameter Control Governance-gated risk parameters + emergency controls (typical DeFi risk-admin pattern) Governance-gated parameters; admin/guardian controls for emergencies (especially during upgrades) Fully governance-controlled parameters; emergency shutdown and circuit breakers exist Parameter updates controlled through governance actions on the Spark Agent (risk, budgets, onboarding, deployments) (Spark Docs) Governance whitelists key risk parameters (LLTVs, IRMs) and can toggle fee switch (capped) (docs.morpho.org)": "Governance-gated parameters; emergency controls informed by v1 lessons", "Practitioner Validation Check YES creates credit onchain • YES liquidation rules enforced by contracts (HF<1) (aave.com) • YES positions unwindable programmatically YES creates credit onchain • YES liquidation enforced by contracts • YES positions unwindable programmatically YES creates credit onchain • YES liquidation enforced via protocol auctions • YES positions unwindable programmatically YES creates credit onchain • YES liquidation rules enforced (HF<1) (Spark Docs) • YES positions unwindable programmatically YES creates credit onchain • YES liquidation enforced (LTV>LLTV) (docs.morpho.org) • YES positions unwindable programmatically": "YES creates credit onchain • YES liquidation enforced • YES positions unwindable programmatically", "Practitioner’s Note Research focus: liquidation mechanics (health factor dynamics), collateral mix concentration, oracle coverage/fallbacks, and governance latency during fast markets. Also track version/market fragmentation (v1 frozen vs v3 active) when analyzing risk. (messari.io) Research focus: differences between v2 and v3 risk profiles; base-asset concentration in v3; liquidation throughput under stress; governance response speed during incidents. Research focus: auction efficiency during stress, oracle latency, RWA exposure and offchain enforcement risk, governance concentration, and emergency shutdown assumptions. Watchpoints: Aave v3 fork deltas (custom DAI/sDAI logic), oracle stack and feed coverage, asset-list governance, and liquidation throughput under stablecoin stress. Also note Spark’s bug bounty posture. (Spark Docs) Watchpoints: oracle selection/config is a first-order risk surface (market-by-market). Validate LLTV choice, oracle robustness, and liquidation liquidity for collateral. Review post-mortems for oracle manipulation and operational incidents. (Morpho Governance Forum)": "Critical context: Euler v1 suffered a major exploit (2023). v2 is a ground-up redesign. Practitioners must treat v2 as a new risk surface, validate audits, and avoid extrapolating v1 assumptions.", "Primary Role in DeFi Base credit + leverage layer for Ethereum DeFi Base credit layer and leverage primitive for Ethereum DeFi Stablecoin issuance + base credit layer for DeFi DAI-centered credit & liquidity venue; major stablecoin + ETH collateral borrowing/supply rails inside Sky ecosystem (Blockworks) Base lending primitive for permissionless risk markets; “lending infrastructure” others build vaults/allocators on top of": "High-flexibility credit layer for long-tail and experimental assets", "Protocol Status Active (v3 widely used; v1 largely frozen) (messari.io) Active (v3 “Comet” is primary; v2 largely deprecated/frozen for growth) Active (DAI issuance core to Ethereum DeFi) Active Active": "Active (v2 live; v1 deprecated after exploit)", "Reason for Inclusion Meets criteria: onchain borrowing/lending; collateralized credit issuance; onchain interest rate mechanics; liquidation + solvency enforced by protocol logic. (aave.com) Meets criteria: issues credit onchain against collateral; defines interest rates, liquidation logic, and solvency rules fully in smart contracts. Meets criteria: onchain borrowing; collateralized credit issuance; explicit liquidation and solvency logic; interest (stability fees) set and enforced onchain. Meets criteria: onchain borrowing/lending, collateralized credit issuance, onchain interest + liquidation + solvency rules. (Spark Docs) Meets criteria: creates credit and enforces liquidation/solvency fully onchain; interest and risk logic are protocol-defined per market. (docs.morpho.org)": "Meets criteria: creates credit onchain, enforces liquidation and solvency via smart contracts, and defines interest mechanics per asset.", "Systemic Risk Exposure High (systemically important liquidity + collateral hub) High (core, long-lived DeFi credit primitive with broad integrations) Very High (DAI is systemically embedded across DeFi and beyond) High (meaningful stablecoin and ETH market integration within Sky ecosystem) (Blockworks) High (rapidly becoming core lending primitive; systemic exposure rises with integration density)": "Medium–High (v2 adoption growing, but systemic footprint smaller than Aave/Compound)", "Upstream Dependencies DEX liquidity for liquidation execution; oracle networks; stablecoin liquidity; governance/risk stewards Oracles (Chainlink); DEX liquidity for liquidation execution; stablecoin liquidity Oracles; keeper/liquidation infrastructure; governance processes; real-world legal structures (for RWAs) Oracles; DEX liquidity for liquidation execution; Sky/Maker liquidity inputs; governance operations (Blockworks) Oracles; liquidator/keeper ecosystem; market curation/allocators; DEX liquidity for liquidation execution": "Oracles; DEX liquidity for liquidation; governance/risk modules"}, "source_label": "Lending Markets"}'::jsonb),
  ('silo-finance', 'Silo Finance', 'defi-systems-architecture', 'lending-markets', 'https://www.silo.finance', ARRAY['Over-collateralized borrowing per isolated market']::text[], ARRAY[]::text[], '{"description": "A lending protocol where each asset exists in its own isolated market, preventing contagion between assets while still enabling permissionless lending.", "extras": {"Collateral Types Supported ERC-20s; ETH; widely supports LST collateral in certain markets (risk-parameter dependent) ERC-20s; ETH (wrapped); selected stablecoins; LST support market-dependent (primarily via governance-approved assets) ETH; ERC-20s; selected LSTs; RWAs (via specialized vaults) ERC-20s + ETH (incl. stETH, DAI, sDAI at launch; asset set is governance/risk-managed) (TradingView) ERC-20s; market-defined collateral/loan pairs (including LSTs, stablecoins, and other ERC-20 collateral depending on market config) (docs.morpho.org)": "ERC-20s; ETH-derived assets; LSTs and long-tail assets silo-by-silo", "Dependency Concentration Risk High oracle reliance + large-collateral concentration risk (market-dependent); governance/parameter-change latency risk High oracle reliance; Medium–High asset concentration risk in v3 base asset; governance latency risk High oracle reliance; High governance concentration risk; Medium–High RWA dependency risk High oracle reliance + governance/parameter-change latency risk; asset concentration risk (DAI-centric design) (Spark Docs) High oracle dependence (per-market); configuration/parameter risk; integration/curation risk (markets can be permissionlessly created but quality varies) (mixbytes.io)": "Medium oracle reliance; low contagion risk by design; silo-specific liquidity risk", "Downstream Consumers Yield strategies, leveraged LPs, hedged carry, structured products, derivatives margin users Yield strategies, leveraged positions, DAO treasuries, arbitrage and carry strategies DEX liquidity, lending protocols, yield strategies, derivatives, DAOs, payment rails Yield strategies, stablecoin allocators, leverage users, structured products integrating DAI liquidity Vaults/allocators, structured lending products, leveraged strategies, institutional deployers using Morpho rails": "Yield strategies, DAOs, niche asset liquidity providers", "Governance Model Token governance (AAVE) via Aave DAO processes; proposals/voting for parameter changes (aave.com) Token governance (COMP) via Compound DAO proposals and voting Token governance (MKR) with executive votes and onchain spell execution Governance via SPK token; Snapshot/signaling and governance system documented by Spark (Spark Docs) Token governance via MORPHO; weighted voting and defined governance powers (docs.morpho.org)": "Token governance (SILO)", "Historical Stress Events Yes (v1 largely frozen/disabled for new supply/borrow; legacy positions remain manageable) (messari.io) Yes (v2 experienced stress events and governance interventions; migration to v3 reflects risk simplification lessons) Yes (notably March 2020 “Black Thursday” auction failures; subsequent mechanism redesigns) No major protocol-loss event cited in core docs; treat as “monitor” (bug bounty active) (Immunefi) Yes (documented oracle-manipulation event on a specific market; plus a frontend-related incident where contracts unaffected) (Morpho Governance Forum)": "No major protocol-level exploit widely cited as of latest documentation", "Interest Rate Model Utilization-based variable rates; also supports “stable” borrow rate mode (market-specific) Utilization-based interest rate curves per asset (v2); simplified rate model with base/borrow asset separation (v3) Governance-set stability fees per vault type (effectively interest rates) Utilization-based IR model (Aave v3 lineage) + custom DAI/sDAI strategies in Spark context (Medium) Market-selected Interest Rate Models (IRMs); IRMs/LLTVs are constrained by governance whitelists (docs.morpho.org)": "Utilization-based interest rates per silo", "Isolation of Risk Risk primarily at market/reserve parameter level (not isolated per-user); isolation features exist in newer versions/markets but not “isolated pools” by default Moderate isolation: v3 introduces asset isolation via a single base asset with segmented collateral; v2 uses shared pools High isolation at vault-type level; each collateral type has independent parameters Shared pool risk by asset/reserve parameters (not per-market isolation like Morpho Blue) High isolation: each market is isolated and immutable by design (docs.morpho.org)": "Very high isolation — each asset silo is independent by design", "Launch Year 2020 (v1 Ethereum mainnet) (aave.com) 2018 (v2 on Ethereum) 2017 (Single-Collateral DAI; Multi-Collateral DAI in 2019) 2023 (public launch May 9, 2023) (X (formerly Twitter)) 2023 (Morpho Blue introduced Oct 2023) (morpho.org)": "2022", "Lending Model Pooled liquidity markets (multi-asset) Pooled liquidity markets (v2); single-collateral base with isolated borrow assets (v3/Comet) CDP / Vault-based collateralized lending Pooled liquidity markets (Aave v3-derived money market) (Spark Docs) Permissionless, isolated lending markets (1 collateral + 1 loan asset per market) (docs.morpho.org)": "Fully isolated, per-asset lending markets (“one asset per silo”)", "Liquidation Mechanism Onchain liquidations triggered when Health Factor < 1; liquidators repay debt for collateral + bonus (bonus/thresholds per asset, governance/risk-managed) (aave.com) Onchain liquidations when collateral value breaches borrow limits; liquidators repay debt for collateral at protocol-defined incentives Onchain liquidation via auctions (debt, collateral, surplus); keeper participation required Health Factor-based liquidations (HF < 1), onchain seizure/repay mechanics (Spark Docs) Standard liquidation when LTV exceeds LLTV; liquidators repay debt and seize collateral at discount (protocol-enforced) (docs.morpho.org)": "Onchain liquidations per silo; no cross-asset contagion", "Maintaining Organization Aave DAO (governance) + Aave Labs (major dev & interface/operator tooling) (aave.com) Compound DAO (governance) with historical development by Compound Labs MakerDAO (DAO-governed protocol) with core units / contributors maintaining modules Spark Governance (SPK) operating via the Spark Agent in the Sky Atlas (Sky ecosystem) (Spark Docs) Morpho Governance (MORPHO token); governance whitelists IRMs/LLTVs and can activate fee switch (docs.morpho.org)": "Silo DAO (SILO token) with core contributors maintaining protocol", "Oracle Dependencies Primarily Chainlink price feeds with protocol risk controls (market-config dependent) Chainlink price feeds (primary), with protocol-defined fallbacks/guards Decentralized Oracle Network (Maker Oracles) with Chainlink integrations and redundancy Oracle-driven risk system; Spark has integrated oracle providers (e.g., RedStone) for lending markets (RedStone blog) Oracle per market; Morpho established an oracle wrapper for Chainlink feeds to support initial markets (morpho.org)": "Chainlink oracles (primary)", "Parameter Control Governance-gated risk parameters + emergency controls (typical DeFi risk-admin pattern) Governance-gated parameters; admin/guardian controls for emergencies (especially during upgrades) Fully governance-controlled parameters; emergency shutdown and circuit breakers exist Parameter updates controlled through governance actions on the Spark Agent (risk, budgets, onboarding, deployments) (Spark Docs) Governance whitelists key risk parameters (LLTVs, IRMs) and can toggle fee switch (capped) (docs.morpho.org)": "Governance-gated parameters per silo; conservative defaults", "Practitioner Validation Check YES creates credit onchain • YES liquidation rules enforced by contracts (HF<1) (aave.com) • YES positions unwindable programmatically YES creates credit onchain • YES liquidation enforced by contracts • YES positions unwindable programmatically YES creates credit onchain • YES liquidation enforced via protocol auctions • YES positions unwindable programmatically YES creates credit onchain • YES liquidation rules enforced (HF<1) (Spark Docs) • YES positions unwindable programmatically YES creates credit onchain • YES liquidation enforced (LTV>LLTV) (docs.morpho.org) • YES positions unwindable programmatically": "YES creates credit onchain • YES liquidation enforced • YES positions unwindable programmatically", "Practitioner’s Note Research focus: liquidation mechanics (health factor dynamics), collateral mix concentration, oracle coverage/fallbacks, and governance latency during fast markets. Also track version/market fragmentation (v1 frozen vs v3 active) when analyzing risk. (messari.io) Research focus: differences between v2 and v3 risk profiles; base-asset concentration in v3; liquidation throughput under stress; governance response speed during incidents. Research focus: auction efficiency during stress, oracle latency, RWA exposure and offchain enforcement risk, governance concentration, and emergency shutdown assumptions. Watchpoints: Aave v3 fork deltas (custom DAI/sDAI logic), oracle stack and feed coverage, asset-list governance, and liquidation throughput under stablecoin stress. Also note Spark’s bug bounty posture. (Spark Docs) Watchpoints: oracle selection/config is a first-order risk surface (market-by-market). Validate LLTV choice, oracle robustness, and liquidation liquidity for collateral. Review post-mortems for oracle manipulation and operational incidents. (Morpho Governance Forum)": "Key advantage: structural isolation dramatically limits systemic contagion. Key tradeoff: lower capital efficiency and fragmented liquidity. Validate oracle quality and liquidation depth per silo.", "Primary Role in DeFi Base credit + leverage layer for Ethereum DeFi Base credit layer and leverage primitive for Ethereum DeFi Stablecoin issuance + base credit layer for DeFi DAI-centered credit & liquidity venue; major stablecoin + ETH collateral borrowing/supply rails inside Sky ecosystem (Blockworks) Base lending primitive for permissionless risk markets; “lending infrastructure” others build vaults/allocators on top of": "Risk-isolated lending infrastructure for long-tail and volatile assets", "Protocol Status Active (v3 widely used; v1 largely frozen) (messari.io) Active (v3 “Comet” is primary; v2 largely deprecated/frozen for growth) Active (DAI issuance core to Ethereum DeFi) Active Active": "Active", "Reason for Inclusion Meets criteria: onchain borrowing/lending; collateralized credit issuance; onchain interest rate mechanics; liquidation + solvency enforced by protocol logic. (aave.com) Meets criteria: issues credit onchain against collateral; defines interest rates, liquidation logic, and solvency rules fully in smart contracts. Meets criteria: onchain borrowing; collateralized credit issuance; explicit liquidation and solvency logic; interest (stability fees) set and enforced onchain. Meets criteria: onchain borrowing/lending, collateralized credit issuance, onchain interest + liquidation + solvency rules. (Spark Docs) Meets criteria: creates credit and enforces liquidation/solvency fully onchain; interest and risk logic are protocol-defined per market. (docs.morpho.org)": "Meets criteria: issues credit against collateral onchain; liquidation and solvency are enforced per-silo via smart contracts.", "Systemic Risk Exposure High (systemically important liquidity + collateral hub) High (core, long-lived DeFi credit primitive with broad integrations) Very High (DAI is systemically embedded across DeFi and beyond) High (meaningful stablecoin and ETH market integration within Sky ecosystem) (Blockworks) High (rapidly becoming core lending primitive; systemic exposure rises with integration density)": "Medium (contained by isolation; lower system-wide blast radius)", "Upstream Dependencies DEX liquidity for liquidation execution; oracle networks; stablecoin liquidity; governance/risk stewards Oracles (Chainlink); DEX liquidity for liquidation execution; stablecoin liquidity Oracles; keeper/liquidation infrastructure; governance processes; real-world legal structures (for RWAs) Oracles; DEX liquidity for liquidation execution; Sky/Maker liquidity inputs; governance operations (Blockworks) Oracles; liquidator/keeper ecosystem; market curation/allocators; DEX liquidity for liquidation execution": "Oracles; DEX liquidity for silo-specific liquidation"}, "source_label": "Lending Markets"}'::jsonb)
) AS v(slug, name, sector_slug, subsector_slug, website, chains, tags, meta)
JOIN public.sectors sec ON sec.slug = v.sector_slug
JOIN public.subsectors s ON s.sector_id = sec.id AND s.slug = v.subsector_slug
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name,
  subsector_id = EXCLUDED.subsector_id,
  website = EXCLUDED.website,
  chains = EXCLUDED.chains,
  tags = EXCLUDED.tags,
  meta = EXCLUDED.meta,
  updated_at = NOW();
